        for i in range(1, n - start + 1):
            segment = q[start:start + i]
            if segment[0] not in used_chars:
                used_chars.add(segment[0])
                if backtrack(start + i, current + [segment], used_chars):
                    return True
                used_chars.remove(segment[0])

        return False

    result = []
    if backtrack(0, [], set()):
        return '\n'.join(['YES'] + [''.join(seq) for seq in result])
    else:
