    from collections import Counter

    # Count the frequency of each character in q
    char_count = Counter(q)

    # Check if each character appears at most k times
    if any(count > k for count in char_count.values()):
        return "NO"

    # Check if the length of q is divisible by k
    if len(q) % k != 0:
        return "NO"

    # Helper function to check if a character can start a new segment
    def can_start_segment(char, used_chars):
        return char not in used_chars

    # Backtracking function to find the beautiful sequence
    def backtrack(start, current_sequence, used_chars):
        if start == len(q):
            return True

        for end in range(start + 1, len(q) + 1):
            segment = q[start:end]
