                used_chars.add(segment[0])
                if backtrack(end, current_sequence, used_chars):
                    return True
                current_sequence.pop()
                used_chars.remove(segment[0])

        return False

    result = []
    if backtrack(0, result, set()):
        return "YES\n" + "\n".join(result)
    else:
        return "NO"

