import heapq
from collections import defaultdict

def find_beautiful_sequence(k, q):
    n = len(q)
    if n < k:
        return "NO"

    char_count = defaultdict(int)
    for char in q:
        char_count[char] += 1

    if max(char_count.values()) > k:
        return "NO"

    pq = []
    for _ in range(k):
        heapq.heappush(pq, ("", 0))

    for char in q:
        current_string, index = heapq.heappop(pq)
        if index == 0:
            heapq.heappush(pq, (current_string + char, 1))
        else:
            heapq.heappush(pq, (current_string + char, index))

    result = [heapq.heappop(pq)[0] for _ in range(k)]
    return "YES\n" + "\n".join(result)

