def find_beautiful_sequence(k, q):
    from collections import defaultdict

    # Count the frequency of each character
    char_count = defaultdict(int)
    for char in q:
        char_count[char] += 1

    # Check if it's possible to form a beautiful sequence
    if max(char_count.values()) > k:
        return "NO"

    # Initialize the result list and a dictionary to keep track of the last position of each character
    result = []
    last_position = {}

    # Iterate through the string and place each character in the appropriate string
    for char in q:
        if char not in last_position:
            # Create a new string if the character hasn't been placed before
            result.append(char)
            last_position[char] = len(result) - 1
        else:
            # Find the next available string to place the character
            for i in range(len(result)):
                if result[i][0] < char:
                    continue
                result[i] += char
                last_position[char] = i
                break
            else:
                # If no suitable string is found, create a new one
                result.append(char)
                last_position[char] = len(result) - 1

    # Return the result
    return "YES\n" + "\n".join(result)

